import {state} from '../../core/state.js?v=9d97c650b6d2';
import {api} from '../../core/api.js?v=9d97c650b6d2';
import {refresh} from '../../core/events.js?v=9d97c650b6d2';
import {T,esc,icon,heading,btn,panel,field,select,textarea,formEnd,modal,closeModal,toast,badge,empty} from '../../core/ui.js?v=9d97c650b6d2';
export async function load(){}
export function render(){const s=state.workspace,p=s.preferences;if(!s.project.can_manage)return empty(T('Dành cho quản lý dự án','Project managers only'),'');return heading(T('Cài đặt dự án','Project settings'),T('Bộ nhãn, hướng dẫn, độ lặp và cấu hình cộng tác được quản lý theo từng dự án.','Manage label schemas, guidelines, redundancy and collaboration per project.'))+`<div class="split-grid"><div class="stack">${panel(T('Thông tin & quy trình','Project information & workflow'),`<form data-submit="settings:save">${field('name',T('Tên dự án','Project name'),s.project.name,'text','required maxlength="180"')}${textarea('description',T('Mô tả','Description'),s.project.description||'')}${textarea('guidelines',T('Hướng dẫn gán nhãn','Annotation guidelines'),p.guidelines,'rows="6"')}${select('redundancy',T('Số người gán trên mỗi mẫu','Annotators per record'),[1,2,3,4,5].map(n=>[n,String(n)]),p.redundancy)}<label class="check-row"><input type="checkbox" name="independent" ${p.independent?'checked':''}>${T('Ẩn gợi ý AI trước khi người gán nộp quyết định','Hide AI suggestions until the annotator submits')}</label><p class="form-hint">${T('Quản lý có quyền giám sát và xuất dữ liệu. Khi đo độc lập, nên tách quản lý khỏi người gán.','Managers can monitor and export data. Separate management and annotation roles for independent measurements.')}</p><label class="check-row"><input name="locked" type="checkbox" ${p.locked?'checked':''}>${T('Khóa thay đổi dữ liệu / gán nhãn','Lock data and annotation changes')}</label><label class="check-row"><input name="archived" type="checkbox" ${p.archived?'checked':''}>${T('Lưu trữ dự án (có thể mở lại)','Archive project (reversible)')}</label>${formEnd(T('Lưu cấu hình','Save settings'))}</form>`)}<div class="info-banner">${icon('shield',18)}<span>${T('Lưu trữ giữ dữ liệu và lịch sử. Nhãn câu, spans, nhãn gold và lượt nghiên cứu được lưu thành những lớp riêng.','Archiving retains data and history. Sentence labels, spans, gold labels and research first passes are separate layers.')}</span></div></div><div class="stack">${panel(T('Bộ nhãn của dự án','Project label schema'),`<div class="schema-list">${s.labels.map(l=>`<article><div class="between">${badge(l.key)}${btn(T('Sửa','Edit'),'settings:label','sm','',`data-key="${esc(l.key)}"`)}</div><code>${esc(l.key)}</code><p>${esc(l.description)}</p>${!l.enabled?`<span class="badge orange">${T('Đã tắt','Disabled')}</span>`:''}</article>`).join('')}</div><div class="flex gap8 mt16">${btn(T('Thêm nhãn','Add label'),'settings:label','','plus')}${btn(T('Dùng preset','Use a preset'),'settings:preset','','layers')}</div>`,T('Key được giữ ổn định; bạn có thể đổi tên, màu và mô tả.','Keys stay stable while names, colors and descriptions remain editable.'))}${panel(T('Thay model và API ở đâu?','Where to change models and APIs?'),`<p class="subtitle">${T('Trang Model & API cho phép chọn phiên bản đã train, tạo kết nối, đổi endpoint và model ID. Không cần sửa giao diện khi thay nhà cung cấp.','Use Models & API to select a trained version, create a connection and change endpoints or model IDs. Switching providers does not require UI changes.')}</p><a class="btn primary mt16" href="#models">${icon('brain',15)}${T('Mở Model & API','Open Models & API')}</a>`)}</div></div>`;}
export async function action(name,el){if(name==='deleteLabel'){const l=state.workspace.labels.find(x=>x.key===el.dataset.key);modal(T('Xóa nhãn chưa sử dụng','Delete an unused label'),`<form data-submit="settings:deleteLabel" data-key="${esc(l.key)}"><p class="form-hint">${T('Nhãn đã dùng không được xóa; có thể tắt để giữ lịch sử. Nhập key để xác nhận.','Used labels are protected; disable them to keep history. Type the key to confirm.')}</p>${field('confirm',l.key,'','text','required')}${formEnd(T('Xóa nhãn','Delete label'))}</form>`);return;}if(name==='label'){const l=state.workspace.labels.find(x=>x.key===el.dataset.key);modal(T('Cấu hình nhãn','Label settings'),`<form data-submit="settings:label">${field('key',T('Key ổn định','Stable key'),l?.key||'','text',`required maxlength="64" ${l?'readonly':''} placeholder="CUSTOM_LABEL"`)}${field('name',T('Tên hiển thị','Display name'),l?.name||'','text','required maxlength="120"')}${field('color',T('Màu','Color'),l?.color||'#4f78a5','color')}${textarea('description',T('Định nghĩa & ví dụ','Definition & examples'),l?.description||'')}${field('order',T('Thứ tự phím tắt','Shortcut order'),l?.order??state.workspace.labels.length,'number','min="0" max="99"')}<label class="check-row"><input name="enabled" type="checkbox" ${l?.enabled===false?'':'checked'}>${T('Đang sử dụng','Enabled')}</label>${formEnd()}</form>${l?`<div class="modal-actions">${btn(T('Xóa nhãn chưa dùng','Delete unused label'),'settings:deleteLabel','danger','',`data-key="${esc(l.key)}"`)}</div>`:''}`);}if(name==='preset')modal(T('Bộ nhãn khởi đầu','Label presets'),`<form data-submit="settings:preset">${select('preset',T('Chọn bộ nhãn','Choose a schema'),[['toxicity',T('Độc hại / Không độc hại','Toxic / Non-toxic')],['hate_speech','CLEAN / OFFENSIVE / HATE']],'toxicity')}<p class="form-hint">${T('Chỉ đổi preset trước khi có nhãn người. Với dự án đã có nhãn, tạo dự án mới hoặc thêm/tắt nhãn riêng để giữ lịch sử.','Switch presets before human annotation begins. For existing annotations, create a new project or add/disable individual labels to retain history.')}</p>${formEnd(T('Áp dụng preset','Apply preset'))}</form>`);}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f)),project=state.workspace.project.id;if(name==='deleteLabel'){const l=state.workspace.labels.find(x=>x.key===f.dataset.key);if(v.confirm!==l.key)throw new Error(T('Key xác nhận chưa khớp.','The confirmation key does not match.'));await api('studio/labels',{project,...l,action:'delete'});}else if(name==='save')await api('studio/project-settings',{...v,project,redundancy:Number(v.redundancy),locked:f.locked.checked,archived:f.archived.checked,independent:f.independent.checked});else await api('studio/labels',{...v,project,enabled:f.enabled?f.enabled.checked:true,order:Number(v.order||0)});closeModal();await refresh();toast(T('Đã lưu cấu hình dự án.','Project settings saved.'));}
